{
  "name": "Drahmi - Production Money Management",
  "description": "A high-performance fintech SaaS for tracking cash, incomes, expenses, and debts with real-time Supabase integration and dark mode UI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface CashRecord {
  id: string;
  user_id: string;
  amount: number;
  updated_at: string;
}

export interface Income {
  id: string;
  user_id: string;
  amount: number;
  currency: string;
  source: string;
  date: string;
  created_at: string;
}

export interface Expense {
  id: string;
  user_id: string;
  title: string;
  amount: number;
  category: string;
  date: string;
  created_at: string;
}

export interface Person {
  id: string;
  user_id: string;
  name: string;
  created_at: string;
}

export interface Debt {
  id: string;
  user_id: string;
  person_id: string;
  amount: number;
  type: 'owe_me' | 'i_owe';
  date: string;
  person?: Person;
}

export interface DashboardStats {
  totalCash: number;
  totalIncome: number;
  totalExpenses: number;
  totalOwedToMe: number;
  totalIOwe: number;
  netBalance: number;
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

if (!supabaseUrl || !supabaseAnonKey) {
  console.warn("Supabase credentials are missing. Ensure SUPABASE_URL and SUPABASE_ANON_KEY are set.");
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import React, { useState, useEffect } from 'react';
import { supabase } from './lib/supabase';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import { User } from '@supabase/supabase-js';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Initial session check
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setUser(session?.user ?? null);
      setLoading(false);
    };

    checkUser();

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950 text-white">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 transition-colors duration-300">
      {user ? (
        <Dashboard user={user} />
      ) : (
        <Auth />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { supabase } from '../lib/supabase';

const Auth: React.FC = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({ email, password });
        if (error) throw error;
        setMessage({ type: 'success', text: 'Check your email for confirmation link!' });
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
      }
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md glass-card p-8 rounded-2xl shadow-2xl">
        <div className="text-center mb-10">
          <h1 className="text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500 mb-2">
            Drahmi
          </h1>
          <p className="text-slate-400">Master your money with precision.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-1">Email Address</label>
            <input
              type="email"
              required
              className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-white"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-1">Password</label>
            <input
              type="password"
              required
              className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-white"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white font-bold py-3 rounded-lg transition-all transform hover:scale-[1.02] active:scale-95 disabled:opacity-50 disabled:transform-none"
          >
            {loading ? 'Processing...' : (isSignUp ? 'Create Account' : 'Sign In')}
          </button>
        </form>

        {message && (
          <div className={`mt-6 p-3 rounded-lg text-sm text-center ${message.type === 'success' ? 'bg-green-500/10 text-green-400 border border-green-500/20' : 'bg-red-500/10 text-red-400 border border-red-500/20'}`}>
            {message.text}
          </div>
        )}

        <div className="mt-8 text-center text-slate-400 text-sm">
          {isSignUp ? "Already have an account?" : "Don't have an account?"}{' '}
          <button
            onClick={() => setIsSignUp(!isSignUp)}
            className="text-blue-400 hover:text-blue-300 font-semibold"
          >
            {isSignUp ? 'Sign In' : 'Sign Up'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { User } from '@supabase/supabase-js';
import { CashRecord, Income, Expense, Debt, Person, DashboardStats } from '../types';
import TransactionList from './TransactionList';
import Modal from './Modal';

interface DashboardProps {
  user: User;
}

const Dashboard: React.FC<DashboardProps> = ({ user }) => {
  const [stats, setStats] = useState<DashboardStats>({
    totalCash: 0,
    totalIncome: 0,
    totalExpenses: 0,
    totalOwedToMe: 0,
    totalIOwe: 0,
    netBalance: 0,
  });

  const [incomes, setIncomes] = useState<Income[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [people, setPeople] = useState<Person[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeModal, setActiveModal] = useState<'income' | 'expense' | 'debt' | 'cash' | null>(null);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);

      const [
        { data: cashData },
        { data: incomeData },
        { data: expenseData },
        { data: debtData },
        { data: peopleData }
      ] = await Promise.all([
        supabase.from('cash').select('*').single(),
        supabase.from('incomes').select('*').order('date', { ascending: false }),
        supabase.from('expenses').select('*').order('date', { ascending: false }),
        supabase.from('debts').select('*, people(*)').order('date', { ascending: false }),
        supabase.from('people').select('*')
      ]);

      const totalCash = (cashData as CashRecord)?.amount || 0;
      const totalIncome = (incomeData as Income[])?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalExpenses = (expenseData as Expense[])?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalOwedToMe = (debtData as Debt[])?.filter(d => d.type === 'owe_me').reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalIOwe = (debtData as Debt[])?.filter(d => d.type === 'i_owe').reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;

      setStats({
        totalCash,
        totalIncome,
        totalExpenses,
        totalOwedToMe,
        totalIOwe,
        netBalance: totalCash + totalOwedToMe - totalIOwe,
      });

      setIncomes(incomeData || []);
      setExpenses(expenseData || []);
      setDebts(debtData || []);
      setPeople(peopleData || []);
    } catch (err) {
      console.error("Error fetching data:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleSignOut = () => supabase.auth.signOut();

  const StatCard = ({ title, value, color }: { title: string, value: number, color: string }) => (
    <div className="glass-card p-6 rounded-2xl shadow-lg border-l-4" style={{ borderColor: color }}>
      <p className="text-slate-400 text-sm font-medium mb-1 uppercase tracking-wider">{title}</p>
      <p className="text-2xl font-bold text-white flex items-baseline">
        <span className="text-slate-500 mr-2 text-sm font-normal">DA</span>
        <span className="animate-pulse-once">{value.toLocaleString()}</span>
      </p>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-10">
        <div>
          <h1 className="text-3xl font-bold text-white">Dashboard</h1>
          <p className="text-slate-400">Welcome back, {user.email?.split('@')[0]}</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => setActiveModal('cash')}
            className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg transition-colors text-sm font-semibold border border-slate-700"
          >
            Update Cash
          </button>
          <button 
            onClick={handleSignOut}
            className="px-4 py-2 bg-red-600/10 hover:bg-red-600/20 text-red-500 rounded-lg transition-colors text-sm font-semibold border border-red-500/20"
          >
            Log Out
          </button>
        </div>
      </div>

      {/* Grid Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-10">
        <StatCard title="Total Cash" value={stats.totalCash} color="#3b82f6" />
        <StatCard title="Total Income" value={stats.totalIncome} color="#10b981" />
        <StatCard title="Total Expenses" value={stats.totalExpenses} color="#ef4444" />
        <StatCard title="Owed To Me" value={stats.totalOwedToMe} color="#8b5cf6" />
        <StatCard title="I Owe" value={stats.totalIOwe} color="#f59e0b" />
        <div className="glass-card p-6 rounded-2xl shadow-lg border-l-4 bg-gradient-to-br from-blue-900/20 to-purple-900/20" style={{ borderColor: '#6366f1' }}>
          <p className="text-slate-300 text-sm font-medium mb-1 uppercase tracking-wider">Net Balance</p>
          <p className={`text-2xl font-bold flex items-baseline ${stats.netBalance >= 0 ? 'text-green-400' : 'text-red-400'}`}>
            <span className="mr-2 text-sm font-normal">DA</span>
            {stats.netBalance.toLocaleString()}
          </p>
        </div>
      </div>

      {/* Action Bar */}
      <div className="flex flex-wrap gap-4 mb-8">
        <button 
          onClick={() => setActiveModal('income')}
          className="flex-1 min-w-[150px] py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl shadow-lg transition-all transform hover:-translate-y-1"
        >
          + Add Income
        </button>
        <button 
          onClick={() => setActiveModal('expense')}
          className="flex-1 min-w-[150px] py-3 bg-rose-600 hover:bg-rose-700 text-white font-bold rounded-xl shadow-lg transition-all transform hover:-translate-y-1"
        >
          + Add Expense
        </button>
        <button 
          onClick={() => setActiveModal('debt')}
          className="flex-1 min-w-[150px] py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg transition-all transform hover:-translate-y-1"
        >
          + Manage Debts
        </button>
      </div>

      {/* Lists */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        <TransactionList 
          title="Recent Activity" 
          incomes={incomes} 
          expenses={expenses} 
          onRefresh={fetchData} 
        />
        <div className="space-y-6">
          <div className="glass-card p-6 rounded-2xl">
            <h2 className="text-xl font-bold mb-4">Current Debts</h2>
            {debts.length === 0 ? (
              <p className="text-slate-500 italic">No debts found.</p>
            ) : (
              <div className="space-y-3">
                {debts.map(debt => (
                  <div key={debt.id} className="flex items-center justify-between p-3 rounded-lg bg-slate-900/50 border border-slate-800">
                    <div>
                      <p className="font-semibold text-white">{debt.person?.name || 'Someone'}</p>
                      <p className={`text-xs ${debt.type === 'owe_me' ? 'text-green-400' : 'text-amber-400'}`}>
                        {debt.type === 'owe_me' ? 'Owes you' : 'You owe them'}
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="font-bold text-white">{Number(debt.amount).toLocaleString()} DA</p>
                      <p className="text-[10px] text-slate-500">{new Date(debt.date).toLocaleDateString()}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Modals */}
      {activeModal && (
        <Modal 
          type={activeModal} 
          people={people} 
          onClose={() => setActiveModal(null)} 
          onSuccess={() => {
            setActiveModal(null);
            fetchData();
          }} 
        />
      )}
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { Income, Expense } from '../types';

interface TransactionListProps {
  title: string;
  incomes: Income[];
  expenses: Expense[];
  onRefresh: () => void;
}

const TransactionList: React.FC<TransactionListProps> = ({ title, incomes, expenses }) => {
  const merged = [
    ...incomes.map(i => ({ ...i, type: 'income' as const })),
    ...expenses.map(e => ({ ...e, type: 'expense' as const, source: e.title })),
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="glass-card p-6 rounded-2xl overflow-hidden">
      <h2 className="text-xl font-bold mb-6 text-white">{title}</h2>
      <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scroll">
        {merged.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-slate-500">No transactions recorded yet.</p>
          </div>
        ) : (
          merged.map((tx) => (
            <div 
              key={tx.id} 
              className="flex items-center justify-between p-4 rounded-xl bg-slate-900/40 border border-slate-800 hover:border-slate-700 transition-colors group"
            >
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${tx.type === 'income' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                  {tx.type === 'income' ? (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 11l5-5m0 0l5 5m-5-5v12"/></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 13l-5 5m0 0l-5-5m5 5V6"/></svg>
                  )}
                </div>
                <div>
                  <h3 className="text-white font-medium group-hover:text-blue-400 transition-colors">
                    {tx.source}
                  </h3>
                  <p className="text-xs text-slate-500">
                    {tx.type === 'expense' ? (tx as any).category : 'Income'} • {new Date(tx.date).toLocaleDateString()}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <p className={`font-bold ${tx.type === 'income' ? 'text-emerald-400' : 'text-rose-400'}`}>
                  {tx.type === 'income' ? '+' : '-'}{Number(tx.amount).toLocaleString()} DA
                </p>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default TransactionList;

import React, { useState } from 'react';
import { supabase } from '../lib/supabase';
import { Person } from '../types';

interface ModalProps {
  type: 'income' | 'expense' | 'debt' | 'cash';
  people: Person[];
  onClose: () => void;
  onSuccess: () => void;
}

const Modal: React.FC<ModalProps> = ({ type, people, onClose, onSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    amount: '',
    source: '',
    title: '',
    category: 'General',
    date: new Date().toISOString().split('T')[0],
    person_name: '',
    person_id: '',
    debt_type: 'owe_me' as 'owe_me' | 'i_owe'
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      if (type === 'income') {
        await supabase.from('incomes').insert([{
          user_id: user.id,
          amount: parseFloat(formData.amount),
          source: formData.source,
          date: formData.date
        }]);
      } else if (type === 'expense') {
        await supabase.from('expenses').insert([{
          user_id: user.id,
          title: formData.title,
          amount: parseFloat(formData.amount),
          category: formData.category,
          date: formData.date
        }]);
      } else if (type === 'cash') {
        const { data: existing } = await supabase.from('cash').select('*').single();
        if (existing) {
          await supabase.from('cash').update({ 
            amount: parseFloat(formData.amount),
            updated_at: new Date().toISOString()
          }).eq('id', existing.id);
        } else {
          await supabase.from('cash').insert([{ 
            user_id: user.id, 
            amount: parseFloat(formData.amount) 
          }]);
        }
      } else if (type === 'debt') {
        let pId = formData.person_id;
        if (!pId && formData.person_name) {
          const { data: newPerson } = await supabase.from('people').insert([{
            user_id: user.id,
            name: formData.person_name
          }]).select().single();
          pId = newPerson?.id;
        }

        if (pId) {
          await supabase.from('debts').insert([{
            user_id: user.id,
            person_id: pId,
            amount: parseFloat(formData.amount),
            type: formData.debt_type,
            date: formData.date
          }]);
        }
      }

      onSuccess();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-md glass-card rounded-2xl p-6 shadow-2xl border border-slate-700 animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-xl font-bold capitalize text-white">Add {type}</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white p-1">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">Amount (DA)</label>
            <input 
              required type="number" step="0.01"
              className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500"
              value={formData.amount}
              onChange={e => setFormData({...formData, amount: e.target.value})}
            />
          </div>

          {type === 'income' && (
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Source</label>
              <input 
                required type="text" placeholder="Salary, Gift, etc."
                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500"
                value={formData.source}
                onChange={e => setFormData({...formData, source: e.target.value})}
              />
            </div>
          )}

          {type === 'expense' && (
            <>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Title</label>
                <input 
                  required type="text" placeholder="Rent, Coffee, etc."
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Category</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value})}
                >
                  <option>General</option>
                  <option>Food</option>
                  <option>Rent</option>
                  <option>Leisure</option>
                  <option>Tech</option>
                  <option>Health</option>
                </select>
              </div>
            </>
          )}

          {type === 'debt' && (
            <>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Person Name</label>
                {people.length > 0 ? (
                   <select 
                   className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500 mb-2"
                   value={formData.person_id}
                   onChange={e => setFormData({...formData, person_id: e.target.value, person_name: ''})}
                 >
                   <option value="">-- New Person --</option>
                   {people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                 </select>
                ) : null}
                {!formData.person_id && (
                  <input 
                    required type="text" placeholder="Enter name"
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500"
                    value={formData.person_name}
                    onChange={e => setFormData({...formData, person_name: e.target.value})}
                  />
                )}
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Type</label>
                <div className="flex gap-2">
                  <button 
                    type="button"
                    onClick={() => setFormData({...formData, debt_type: 'owe_me'})}
                    className={`flex-1 py-2 rounded-lg text-sm font-bold border ${formData.debt_type === 'owe_me' ? 'bg-green-500/20 border-green-500 text-green-400' : 'border-slate-700 text-slate-500'}`}
                  >
                    Owes Me
                  </button>
                  <button 
                    type="button"
                    onClick={() => setFormData({...formData, debt_type: 'i_owe'})}
                    className={`flex-1 py-2 rounded-lg text-sm font-bold border ${formData.debt_type === 'i_owe' ? 'bg-amber-500/20 border-amber-500 text-amber-400' : 'border-slate-700 text-slate-500'}`}
                  >
                    I Owe
                  </button>
                </div>
              </div>
            </>
          )}

          {type !== 'cash' && (
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Date</label>
              <input 
                required type="date"
                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-blue-500"
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />
            </div>
          )}

          <div className="pt-4 flex gap-3">
            <button 
              type="button" onClick={onClose}
              className="flex-1 py-2 rounded-lg text-slate-400 hover:text-white border border-slate-700 transition-colors"
            >
              Cancel
            </button>
            <button 
              type="submit" disabled={loading}
              className="flex-1 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-bold transition-colors disabled:opacity-50"
            >
              {loading ? 'Saving...' : 'Save'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

