          <div className="text-left bg-black/40 p-4 rounded-lg text-xs font-mono text-slate-500">
            1. Create a Supabase project<br/>
            2. Copy URL and Anon Key<br/>
            3. Add to Settings > Environment Variables
          </div>
        </div>
      </div>
    );
