import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { User } from '@supabase/supabase-js';
import { CashRecord, Income, Expense, Debt, Person, DashboardStats } from '../types';
import TransactionList from './TransactionList';
import Modal from './Modal';

interface DashboardProps {
  user: User;
}

type View = 'home' | 'history' | 'debts' | 'settings';

const Dashboard: React.FC<DashboardProps> = ({ user }) => {
  const [activeView, setActiveView] = useState<View>('home');
  const [stats, setStats] = useState<DashboardStats>({
    totalCash: 0,
    totalIncome: 0,
    totalExpenses: 0,
    totalOwedToMe: 0,
    totalIOwe: 0,
    netBalance: 0,
  });

  const [incomes, setIncomes] = useState<Income[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [people, setPeople] = useState<Person[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeModal, setActiveModal] = useState<'income' | 'expense' | 'debt' | 'cash' | null>(null);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);

      const [
        { data: cashData },
        { data: incomeData },
        { data: expenseData },
        { data: debtData },
        { data: peopleData }
      ] = await Promise.all([
        supabase.from('cash').select('*').single(),
        supabase.from('incomes').select('*').order('date', { ascending: false }),
        supabase.from('expenses').select('*').order('date', { ascending: false }),
        supabase.from('debts').select('*, people(*)').order('date', { ascending: false }),
        supabase.from('people').select('*')
      ]);

      const totalCash = (cashData as CashRecord)?.amount || 0;
      const totalIncome = (incomeData as Income[])?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalExpenses = (expenseData as Expense[])?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalOwedToMe = (debtData as Debt[])?.filter(d => d.type === 'owe_me').reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalIOwe = (debtData as Debt[])?.filter(d => d.type === 'i_owe').reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;

      setStats({
        totalCash,
        totalIncome,
        totalExpenses,
        totalOwedToMe,
        totalIOwe,
        netBalance: totalCash + totalOwedToMe - totalIOwe,
      });

      setIncomes(incomeData || []);
      setExpenses(expenseData || []);
      setDebts(debtData || []);
      setPeople(peopleData || []);
    } catch (err) {
      console.error("Error fetching data:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleSignOut = () => supabase.auth.signOut();

  const StatCard = ({ title, value, color }: { title: string, value: number, color: string }) => (
    <div className="glass-card p-5 rounded-2xl shadow-lg border-l-4 transition-all hover:translate-y-[-2px]" style={{ borderColor: color }}>
      <p className="text-slate-500 text-[10px] font-bold mb-1 uppercase tracking-widest">{title}</p>
      <p className="text-xl font-bold text-white flex items-baseline">
        <span className="text-slate-600 mr-1 text-xs font-normal">DA</span>
        {value.toLocaleString()}
      </p>
    </div>
  );

  const NavItem = ({ view, label, icon }: { view: View, label: string, icon: React.ReactNode }) => (
    <button
      onClick={() => setActiveView(view)}
      className={`flex flex-col items-center gap-1 py-2 flex-1 transition-all ${
        activeView === view ? 'text-blue-500 scale-110' : 'text-slate-600 hover:text-slate-300'
      }`}
    >
      {icon}
      <span className="text-[10px] font-bold uppercase tracking-tighter">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen pb-24 max-w-lg mx-auto px-4 pt-6">
      {/* View Header */}
      <header className="flex items-center justify-between mb-8 px-2">
        <div>
          <h1 className="text-3xl font-bold text-white tracking-tight">
            {activeView === 'home' ? 'Summary' : activeView.charAt(0).toUpperCase() + activeView.slice(1)}
          </h1>
          <p className="text-xs text-slate-500 font-medium">
            {new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
          </p>
        </div>
        <div className="flex gap-2">
          {activeView === 'home' && (
             <button 
              onClick={() => setActiveModal('cash')}
              className="p-3 bg-blue-600/10 border border-blue-500/20 rounded-2xl hover:bg-blue-600/20 transition-all text-blue-400"
              title="Update Balance"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 1.343-3 3s1.343 3 3 3 3-1.343 3-3-1.343-3-3-3zM12 2C6.477 2 2 6.477 2 12s4.477 10 10 10 10-4.477 10-10S17.523 2 12 2z"/></svg>
            </button>
          )}
        </div>
      </header>

      {/* Main View Transitions */}
      <div className="transition-all duration-300 animate-in fade-in slide-in-from-bottom-2">
        {activeView === 'home' && (
          <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <StatCard title="Wallet Balance" value={stats.totalCash} color="#3b82f6" />
              <StatCard title="Total Worth" value={stats.netBalance} color="#6366f1" />
              <StatCard title="Gross Income" value={stats.totalIncome} color="#10b981" />
              <StatCard title="Gross Spent" value={stats.totalExpenses} color="#ef4444" />
              <StatCard title="Receivables" value={stats.totalOwedToMe} color="#8b5cf6" />
