import React from 'react';
import { Income, Expense } from '../types';

interface TransactionListProps {
  title: string;
  incomes: Income[];
  expenses: Expense[];
  onRefresh: () => void;
}

const TransactionList: React.FC<TransactionListProps> = ({ title, incomes, expenses }) => {
  const merged = [
    ...incomes.map(i => ({ ...i, type: 'income' as const })),
    ...expenses.map(e => ({ ...e, type: 'expense' as const, source: e.title })),
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="glass-card p-8 rounded-[40px] border-slate-800/40">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-lg font-bold text-white tracking-tight">{title}</h2>
        <span className="text-[10px] bg-white/5 text-slate-500 font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-white/5">
          {merged.length} Events
        </span>
      </div>

      <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2 custom-scroll">
        {merged.length === 0 ? (
          <div className="text-center py-24 opacity-20">
            <p className="text-slate-400 text-sm italic">Nothing tracked yet.</p>
          </div>
        ) : (
          merged.map((tx, idx) => (
            <div 
              key={tx.id} 
              className="flex items-center justify-between p-5 rounded-[28px] bg-slate-900/30 border border-slate-800/60 hover:border-blue-500/30 hover:bg-slate-900/60 transition-all group animate-in fade-in slide-in-from-right-4 duration-300"
              style={{ animationDelay: `${idx * 50}ms` }}
            >
              <div className="flex items-center gap-5">
                <div className={`w-12 h-12 rounded-[18px] flex items-center justify-center transition-transform group-hover:rotate-6 ${
                  tx.type === 'income' 
                    ? 'bg-emerald-500/10 text-emerald-500' 
                    : 'bg-rose-500/10 text-rose-500'
                }`}>
                  {tx.type === 'income' ? (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M20 12H4"/></svg>
                  )}
                </div>
                <div>
                  <h3 className="text-white font-bold text-sm tracking-tight group-hover:text-blue-400 transition-colors">
                    {tx.source}
                  </h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">
                    {tx.type === 'expense' ? (tx as any).category : 'Income'} • {new Date(tx.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <p className={`font-black text-sm tracking-tighter ${tx.type === 'income' ? 'text-emerald-400' : 'text-rose-400'}`}>
                  {tx.type === 'income' ? '+' : '-'}{Number(tx.amount).toLocaleString()}
                </p>
                <p className="text-[8px] text-slate-700 uppercase tracking-widest font-black">DA</p>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

