import React, { useState } from 'react';
import { supabase } from '../lib/supabase';
import { Person } from '../types';

interface ModalProps {
  type: 'income' | 'expense' | 'debt' | 'cash';
  people: Person[];
  onClose: () => void;
  onSuccess: () => void;
}

const Modal: React.FC<ModalProps> = ({ type, people, onClose, onSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    amount: '',
    source: '',
    title: '',
    category: 'General',
    date: new Date().toISOString().split('T')[0],
    person_name: '',
    person_id: '',
    debt_type: 'owe_me' as 'owe_me' | 'i_owe'
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      if (type === 'income') {
        await supabase.from('incomes').insert([{ user_id: user.id, amount: parseFloat(formData.amount), source: formData.source, date: formData.date }]);
      } else if (type === 'expense') {
        await supabase.from('expenses').insert([{ user_id: user.id, title: formData.title, amount: parseFloat(formData.amount), category: formData.category, date: formData.date }]);
      } else if (type === 'cash') {
        const { data: existing } = await supabase.from('cash').select('*').single();
        if (existing) {
          await supabase.from('cash').update({ amount: parseFloat(formData.amount), updated_at: new Date().toISOString() }).eq('id', existing.id);
        } else {
          await supabase.from('cash').insert([{ user_id: user.id, amount: parseFloat(formData.amount) }]);
        }
      } else if (type === 'debt') {
        let pId = formData.person_id;
        if (!pId && formData.person_name) {
          const { data: newPerson } = await supabase.from('people').insert([{ user_id: user.id, name: formData.person_name }]).select().single();
          pId = newPerson?.id;
        }
        if (pId) {
          await supabase.from('debts').insert([{ user_id: user.id, person_id: pId, amount: parseFloat(formData.amount), type: formData.debt_type, date: formData.date }]);
        }
      }
      onSuccess();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-md px-0 sm:px-4">
      {/* Background overlay click to close */}
      <div className="absolute inset-0" onClick={onClose}></div>

      <div className="w-full max-w-md modal-content glass-card rounded-t-[40px] sm:rounded-[40px] p-8 pb-12 sm:pb-8 shadow-2xl border-white/10 animate-slide-up relative z-10">
        {/* Handle for bottom sheet visual */}
        <div className="w-12 h-1.5 bg-slate-700 rounded-full mx-auto mb-6 sm:hidden opacity-50"></div>

        <div className="flex items-center justify-between mb-8">
          <h2 className="text-2xl font-black text-white tracking-tight capitalize">Add {type}</h2>
          <button onClick={onClose} className="p-2 bg-white/5 rounded-full text-slate-400 hover:text-white transition-colors">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 ml-1">Amount (DA)</label>
            <input 
              required type="number" step="0.01" placeholder="0.00"
              className="w-full h-14 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-xl font-bold text-white outline-none focus:ring-2 focus:ring-blue-500 transition-all placeholder:text-slate-700"
              value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})}
            />
          </div>

          {type === 'income' && (
            <div className="space-y-2">
              <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 ml-1">Source</label>
              <input 
                required type="text" placeholder="Salary, Gift, Sale..."
                className="w-full h-14 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-blue-500"
                value={formData.source} onChange={e => setFormData({...formData, source: e.target.value})}
              />
            </div>
          )}

          {type === 'expense' && (
            <>
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 ml-1">Title</label>
                <input 
                  required type="text" placeholder="What did you buy?"
                  className="w-full h-14 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-blue-500"
                  value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})}
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 ml-1">Category</label>
                <select 
                  className="w-full h-14 bg-slate-900 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-blue-500 appearance-none"
                  value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}
                >
                  <option>General</option>
                  <option>Food & Drinks</option>
                  <option>Transport</option>
                  <option>Shopping</option>
                  <option>Entertainment</option>
                  <option>Health</option>
                </select>
              </div>
            </>
          )}

          {type === 'debt' && (
            <>
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 ml-1">Recipient/Sender</label>
                {people.length > 0 && (
                   <select 
                   className="w-full h-14 bg-slate-900 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-blue-500 mb-2 appearance-none"
                   value={formData.person_id} onChange={e => setFormData({...formData, person_id: e.target.value, person_name: ''})}
                 >
                   <option value="">-- New Person --</option>
                   {people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                 </select>
                )}
                {!formData.person_id && (
                  <input 
                    required type="text" placeholder="Full name"
                    className="w-full h-14 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-blue-500"
                    value={formData.person_name} onChange={e => setFormData({...formData, person_name: e.target.value})}
                  />
                )}
              </div>
              <div className="grid grid-cols-2 gap-3">
                <button 
                  type="button" onClick={() => setFormData({...formData, debt_type: 'owe_me'})}
                  className={`py-4 rounded-2xl text-xs font-bold border transition-all ${formData.debt_type === 'owe_me' ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : 'border-white/10 text-slate-500'}`}
                >
                  THEY OWE ME
                </button>
                <button 
                  type="button" onClick={() => setFormData({...formData, debt_type: 'i_owe'})}
                  className={`py-4 rounded-2xl text-xs font-bold border transition-all ${formData.debt_type === 'i_owe' ? 'bg-amber-500/20 border-amber-500 text-amber-400' : 'border-white/10 text-slate-500'}`}
                >
                  I OWE THEM
                </button>
              </div>
            </>
          )}

          {type !== 'cash' && (
            <div className="space-y-2">
              <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 ml-1">Transaction Date</label>
              <input 
                required type="date"
                className="w-full h-14 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-blue-500"
                value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})}
              />
            </div>
          )}

          <div className="pt-4 space-y-3">
            <button 
              type="submit" disabled={loading}
              className="w-full h-16 bg-blue-600 hover:bg-blue-500 text-white font-black text-lg rounded-2xl shadow-xl shadow-blue-600/20 active:scale-95 transition-all disabled:opacity-50"
            >
              {loading ? 'PROCESSING...' : 'CONFIRM TRANSACTION'}
            </button>
            <button 
              type="button" onClick={onClose}
              className="w-full py-4 text-slate-500 font-bold hover:text-white transition-colors"
            >
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Modal;

import React from 'react';
import { Income, Expense } from '../types';

interface TransactionListProps {
  title: string;
  incomes: Income[];
  expenses: Expense[];
  onRefresh: () => void;
}

const TransactionList: React.FC<TransactionListProps> = ({ title, incomes, expenses }) => {
  const merged = [
    ...incomes.map(i => ({ ...i, type: 'income' as const })),
    ...expenses.map(e => ({ ...e, type: 'expense' as const, source: e.title })),
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="glass-card rounded-[32px] p-6 border-slate-800/50">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-xl font-black text-white tracking-tight">{title}</h2>
        <span className="text-[9px] bg-blue-600/10 text-blue-400 font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-blue-500/10">
          {merged.length} Logs
        </span>
      </div>

      <div className="space-y-3">
        {merged.length === 0 ? (
          <div className="text-center py-20 opacity-30">
            <p className="text-slate-400 text-sm italic">Nothing tracked yet.</p>
          </div>
        ) : (
          merged.map((tx, idx) => (
            <div 
              key={tx.id} 
              className="flex items-center justify-between p-4 rounded-2xl bg-white/5 border border-white/5 active:bg-white/10 transition-colors group animate-in slide-in-from-right-4 duration-300"
              style={{ animationDelay: `${idx * 60}ms` }}
            >
              <div className="flex items-center gap-4">
                <div className={`w-11 h-11 rounded-xl flex items-center justify-center transition-transform group-active:scale-90 ${
                  tx.type === 'income' 
                    ? 'bg-emerald-500/10 text-emerald-500' 
                    : 'bg-rose-500/10 text-rose-500'
                }`}>
                  {tx.type === 'income' ? (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M20 12H4"/></svg>
                  )}
                </div>
                <div>
                  <h3 className="text-white font-bold text-sm truncate max-w-[140px]">
                    {tx.source}
                  </h3>
                  <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-1">
                    {tx.type === 'expense' ? (tx as any).category : 'Deposit'} • {new Date(tx.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <p className={`font-black text-sm tracking-tighter ${tx.type === 'income' ? 'text-emerald-400' : 'text-rose-400'}`}>
                  {tx.type === 'income' ? '+' : '-'}{Number(tx.amount).toLocaleString()}
                </p>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default TransactionList;

import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { User } from '@supabase/supabase-js';
import { CashRecord, Income, Expense, Debt, Person, DashboardStats } from '../types';
import TransactionList from './TransactionList';
import Modal from './Modal';

interface DashboardProps {
  user: User;
}

type View = 'home' | 'history' | 'debts' | 'settings';

const Dashboard: React.FC<DashboardProps> = ({ user }) => {
  const [activeView, setActiveView] = useState<View>('home');
  const [stats, setStats] = useState<DashboardStats>({
    totalCash: 0,
    totalIncome: 0,
    totalExpenses: 0,
    totalOwedToMe: 0,
    totalIOwe: 0,
    netBalance: 0,
  });

  const [incomes, setIncomes] = useState<Income[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [people, setPeople] = useState<Person[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeModal, setActiveModal] = useState<'income' | 'expense' | 'debt' | 'cash' | null>(null);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const [
        { data: cashData },
        { data: incomeData },
        { data: expenseData },
        { data: debtData },
        { data: peopleData }
      ] = await Promise.all([
        supabase.from('cash').select('*').single(),
        supabase.from('incomes').select('*').order('date', { ascending: false }),
        supabase.from('expenses').select('*').order('date', { ascending: false }),
        supabase.from('debts').select('*, people(*)').order('date', { ascending: false }),
        supabase.from('people').select('*')
      ]);

      const totalCash = (cashData as CashRecord)?.amount || 0;
      const totalIncome = (incomeData as Income[])?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalExpenses = (expenseData as Expense[])?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalOwedToMe = (debtData as Debt[])?.filter(d => d.type === 'owe_me').reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;
      const totalIOwe = (debtData as Debt[])?.filter(d => d.type === 'i_owe').reduce((acc, curr) => acc + Number(curr.amount), 0) || 0;

      setStats({
        totalCash,
        totalIncome,
        totalExpenses,
        totalOwedToMe,
        totalIOwe,
        netBalance: totalCash + totalOwedToMe - totalIOwe,
      });

      setIncomes(incomeData || []);
      setExpenses(expenseData || []);
      setDebts(debtData || []);
      setPeople(peopleData || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const NavItem = ({ view, label, icon }: { view: View, label: string, icon: React.ReactNode }) => (
    <button
      onClick={() => setActiveView(view)}
