import React, { useState } from 'react';
import { supabase } from '../lib/supabase';
import { Person } from '../types';

interface ModalProps {
  type: 'income' | 'expense' | 'debt' | 'cash';
  people: Person[];
  onClose: () => void;
  onSuccess: () => void;
}

const Modal: React.FC<ModalProps> = ({ type, people, onClose, onSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    amount: '',
    source: '',
    title: '',
    category: 'General',
    date: new Date().toISOString().split('T')[0],
    person_name: '',
    person_id: '',
    debt_type: 'owe_me' as 'owe_me' | 'i_owe'
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const amt = parseFloat(formData.amount);
      if (isNaN(amt)) return;

      if (type === 'income') {
        await supabase.from('incomes').insert([{ user_id: user.id, amount: amt, source: formData.source, date: formData.date }]);
      } else if (type === 'expense') {
        await supabase.from('expenses').insert([{ user_id: user.id, title: formData.title, amount: amt, category: formData.category, date: formData.date }]);
      } else if (type === 'cash') {
        const { data: existing } = await supabase.from('cash').select('*').single();
        if (existing) {
          await supabase.from('cash').update({ amount: amt, updated_at: new Date().toISOString() }).eq('id', existing.id);
        } else {
          await supabase.from('cash').insert([{ user_id: user.id, amount: amt }]);
        }
      } else if (type === 'debt') {
        let pId = formData.person_id;
        if (!pId && formData.person_name) {
          const { data: newPerson } = await supabase.from('people').insert([{ user_id: user.id, name: formData.person_name }]).select().single();
          pId = newPerson?.id;
        }
        if (pId) {
          await supabase.from('debts').insert([{ user_id: user.id, person_id: pId, amount: amt, type: formData.debt_type, date: formData.date }]);
        }
      }
      onSuccess();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center bg-black/80 backdrop-blur-xl px-0 sm:px-4">
      <div className="absolute inset-0" onClick={onClose}></div>

      <div className="w-full max-w-md glass rounded-t-[50px] sm:rounded-[48px] p-10 pb-16 sm:pb-10 shadow-2xl border-white/10 animate-slide-up relative z-10">
        <div className="w-16 h-1.5 bg-slate-800 rounded-full mx-auto mb-10 sm:hidden"></div>

        <div className="flex items-center justify-between mb-12">
          <h2 className="text-3xl font-black text-white tracking-tighter capitalize">{type} Entry</h2>
          <button onClick={onClose} className="w-12 h-12 glass rounded-2xl text-slate-500 hover:text-white transition-colors flex items-center justify-center">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-3">
            <label className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 ml-1">Magnitude (DA)</label>
            <input 
              required type="number" step="0.01" placeholder="0.00"
              className="w-full h-20 bg-white/5 border border-white/10 rounded-[28px] px-8 text-4xl font-black text-white outline-none focus:ring-2 focus:ring-blue-500 transition-all placeholder:text-slate-800 tracking-tighter"
              value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})}
            />
          </div>

          <div className="space-y-6">
            {type === 'income' && (
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Origin</label>
                <input required type="text" className="w-full h-16 glass rounded-2xl px-6 text-white outline-none focus:ring-2 focus:ring-blue-500" value={formData.source} onChange={e => setFormData({...formData, source: e.target.value})} />
              </div>
            )}

            {type === 'expense' && (
              <>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Destination</label>
                  <input required type="text" className="w-full h-16 glass rounded-2xl px-6 text-white outline-none focus:ring-2 focus:ring-blue-500" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Silo</label>
                  <select className="w-full h-16 glass rounded-2xl px-6 text-white outline-none focus:ring-2 focus:ring-blue-500 appearance-none bg-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                    <option>Lifestyle</option><option>Vitals</option><option>Fixed</option><option>Misc</option>
                  </select>
                </div>
              </>
            )}

            {type === 'debt' && (
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Counterparty</label>
                <input required type="text" className="w-full h-16 glass rounded-2xl px-6 text-white outline-none focus:ring-2 focus:ring-blue-500" value={formData.person_name} onChange={e => setFormData({...formData, person_name: e.target.value})} />
                <div className="grid grid-cols-2 gap-4">
                  <button type="button" onClick={() => setFormData({...formData, debt_type: 'owe_me'})} className={`py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest border transition-all ${formData.debt_type === 'owe_me' ? 'bg-emerald-500 text-slate-950 border-emerald-500' : 'glass text-slate-500 border-white/10'}`}>Owe Me</button>
                  <button type="button" onClick={() => setFormData({...formData, debt_type: 'i_owe'})} className={`py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest border transition-all ${formData.debt_type === 'i_owe' ? 'bg-amber-500 text-slate-950 border-amber-500' : 'glass text-slate-500 border-white/10'}`}>I Owe</button>
                </div>
              </div>
            )}
          </div>

          <div className="pt-6 space-y-4">
            <button 
              type="submit" disabled={loading}
              className="w-full h-20 bg-white text-slate-950 font-black text-lg rounded-[32px] shadow-2xl active-bounce transition-all disabled:opacity-50 uppercase tracking-[0.2em]"
            >
              {loading ? 'Submitting...' : 'Commit Transaction'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Modal;

