                        <div key={goal.id} className="premium-card p-5 border-emerald-500/10">
                          <div className="flex justify-between items-center mb-3">
                            <span className="font-bold text-sm text-white">{goal.name}</span>
                            <span className="text-[10px] font-black text-emerald-500 uppercase">{progress.toFixed(0)}%</span>
                          </div>
                          <div className="w-full bg-white/5 h-2 rounded-full mb-3 overflow-hidden">
                            <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
                          </div>
                          <p className="text-[10px] text-slate-500 font-medium">Target: {goal.target_amount.toLocaleString()} DA</p>
                        </div>
                      )
                    })}
                  </div>
                </div>
              )}

              <div className="space-y-4">
                <div className="flex items-center justify-between px-2">
                   <h4 className="text-xs font-black uppercase tracking-widest text-slate-500">Recent Activity</h4>
                </div>
                <TransactionList title="" incomes={incomes.slice(0, 3)} expenses={expenses.slice(0, 3)} onRefresh={fetchData} />
              </div>
            </>
          )}

          {activeView === 'savings' && (
            <div className="space-y-8 animate-fade-up">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl font-extrabold text-white tracking-tight">Savings Vault</h2>
                <button onClick={() => setActiveModal('savings_goal')} className="h-10 px-4 bg-emerald-600 rounded-xl text-[10px] font-black uppercase tracking-widest text-white interactive-active">New Goal</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {goals.map(goal => {
                  const progress = Math.min((goal.saved_amount / goal.target_amount) * 100, 100);
                  const remaining = goal.target_amount - goal.saved_amount;
                  const estMonths = goal.monthly_amount > 0 ? Math.ceil(remaining / goal.monthly_amount) : '∞';

                  return (
                    <div key={goal.id} className={`premium-card p-8 flex flex-col relative overflow-hidden transition-all ${goal.status === 'completed' ? 'border-emerald-500 shadow-emerald-500/10' : ''}`}>
                      {goal.status === 'completed' && (
                         <div className="absolute top-4 right-4 bg-emerald-500 text-slate-950 text-[8px] font-black px-2 py-1 rounded uppercase tracking-widest">Completed</div>
                      )}

                      <div className="mb-6">
                        <h4 className="text-xl font-bold text-white mb-1">{goal.name}</h4>
                        <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Smart Saving: {goal.monthly_amount.toLocaleString()} DA / Mo</p>
                      </div>

                      <div className="flex items-baseline gap-2 mb-2">
                         <span className="text-3xl font-black text-white">{goal.saved_amount.toLocaleString()}</span>
                         <span className="text-slate-500 text-sm">/ {goal.target_amount.toLocaleString()} DA</span>
                      </div>

                      <div className="w-full bg-white/5 h-4 rounded-full mb-6 overflow-hidden">
                        <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
                      </div>

                      <div className="grid grid-cols-2 gap-4 mt-auto pt-6 border-t border-white/5">
                        <div>
                           <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest mb-1">Time Remaining</p>
                           <p className="text-sm font-bold text-slate-100">{goal.status === 'completed' ? 'Goal Met' : `${estMonths} Months`}</p>
                        </div>
                        <div className="text-right">
                           <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest mb-1">Status</p>
                           <p className={`text-sm font-bold capitalize ${goal.status === 'active' ? 'text-blue-400' : 'text-emerald-400'}`}>{goal.status}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {goals.length === 0 && (
                <div className="text-center py-20 glass rounded-3xl border-dashed border-2 border-white/5">
                  <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4 opacity-50">💰</div>
                  <p className="text-slate-500 font-medium">No savings goals established yet.</p>
                </div>
              )}
            </div>
          )}

          {activeView === 'history' && <TransactionList title="Ledger" incomes={incomes} expenses={expenses} onRefresh={fetchData} />}
          {activeView === 'debts' && (
            <div className="space-y-6 animate-fade-up">
               <div className="premium-card p-6">
                  <h2 className="text-xl font-bold mb-6 tracking-tight text-emerald-400">Receivables</h2>
                  <div className="space-y-3">
                    {debts.filter(d => d.type === 'owe_me').length === 0 ? <p className="text-slate-600 text-xs italic py-4">Clear ledger.</p> :
                      debts.filter(d => d.type === 'owe_me').map(debt => (
                        <div key={debt.id} className="flex items-center justify-between p-4 rounded-2xl bg-white/5 border border-white/5">
                          <span className="font-bold text-sm text-white">{debt.person?.name}</span>
                          <span className="text-emerald-400 font-bold text-sm">+{debt.amount.toLocaleString()}</span>
                        </div>
                      ))
                    }
                  </div>
               </div>
               <div className="premium-card p-6">
                  <h2 className="text-xl font-bold mb-6 tracking-tight text-rose-400">Payables</h2>
                  <div className="space-y-3">
                    {debts.filter(d => d.type === 'i_owe').length === 0 ? <p className="text-slate-600 text-xs italic py-4">No obligations.</p> :
                      debts.filter(d => d.type === 'i_owe').map(debt => (
                        <div key={debt.id} className="flex items-center justify-between p-4 rounded-2xl bg-white/5 border border-white/5">
                          <span className="font-bold text-sm text-white">{debt.person?.name}</span>
                          <span className="text-rose-400 font-bold text-sm">-{debt.amount.toLocaleString()}</span>
                        </div>
                      ))
                    }
                  </div>
               </div>
               <button onClick={() => setActiveModal('debt')} className="w-full h-14 bg-blue-600 rounded-2xl font-black uppercase tracking-widest text-[10px] text-white interactive-active">Register Debt Entry</button>
            </div>
          )}
          {activeView === 'settings' && (
            <div className="max-w-xl mx-auto animate-fade-up">
               <div className="premium-card p-8 text-center flex flex-col items-center">
                  <div className="w-20 h-20 bg-gradient-to-tr from-blue-600 to-indigo-700 rounded-3xl flex items-center justify-center text-3xl font-black mb-6 rotate-3">
                    {user.email?.charAt(0).toUpperCase()}
                  </div>
                  <h3 className="text-2xl font-bold mb-1 tracking-tight">{user.email?.split('@')[0]}</h3>
                  <p className="text-slate-500 text-sm mb-10">{user.email}</p>
                  <button onClick={() => supabase.auth.signOut()} className="w-full h-12 bg-rose-500/10 border border-rose-500/20 text-rose-500 rounded-xl text-[10px] font-black uppercase tracking-widest interactive-active">Terminate Session</button>
               </div>
            </div>
          )}
        </div>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 xl:hidden glass border-t border-white/5 z-[60] pb-safe flex px-2 bg-slate-950/80">
        <TabItem view="home" label="Home" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/></svg>} />
        <TabItem view="history" label="Activity" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>} />
        <TabItem view="savings" label="Savings" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 002-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>} />
        <TabItem view="debts" label="Vault" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857"/></svg>} />
        <TabItem view="settings" label="Profile" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>} />
