-- ==========================================
-- 1. تهيئة الإضافات والأنواع (Extensions & Enums)
-- ==========================================
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- أنواع الديون: 'أدين له' أو 'يدين لي'
CREATE TYPE debt_type AS ENUM ('owe_me', 'i_owe');
-- حالة أهداف الادخار
CREATE TYPE goal_status AS ENUM ('active', 'completed');

-- ==========================================
-- 2. إنشاء الجداول الأساسية (Core Tables)
-- ==========================================

-- جدول النقد الحالي (Cash)
CREATE TABLE public.cash (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
    amount DECIMAL(12, 2) DEFAULT 0.00,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- جدول الدخل (Incomes)
CREATE TABLE public.incomes (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    amount DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    source TEXT NOT NULL,
    date TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- جدول المصاريف (Expenses)
CREATE TABLE public.expenses (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    amount DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    date TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- جدول الأشخاص (People) - دليل جهات الاتصال للديون
CREATE TABLE public.people (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    UNIQUE(user_id, name)
);

-- جدول الديون (Debts)
CREATE TABLE public.debts (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    person_id UUID NOT NULL REFERENCES public.people(id) ON DELETE CASCADE,
    amount DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    type debt_type NOT NULL,
    date TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- جدول أهداف الادخار (Savings Goals)
CREATE TABLE public.savings_goals (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    target_amount DECIMAL(12, 2) NOT NULL CHECK (target_amount > 0),
    monthly_amount DECIMAL(12, 2) DEFAULT 0.00,
    saved_amount DECIMAL(12, 2) DEFAULT 0.00,
    status goal_status DEFAULT 'active',
    last_deduction_date TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

