-- 0. Safety note:
-- Confirm you want to run these changes. They include CREATE EXTENSION IF NOT EXISTS "pgcrypto".
-- If pgcrypto is not permitted in your environment, tell me and I'll provide an alternate version.

-- ==========================================
-- 1. Enable pgcrypto (for gen_random_uuid)
-- ==========================================
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ==========================================
-- 2. Create ENUM types if they don't exist
-- ==========================================
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'debt_type') THEN
    CREATE TYPE debt_type AS ENUM ('owe_me', 'i_owe');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'goal_status') THEN
    CREATE TYPE goal_status AS ENUM ('active', 'completed');
  END IF;
END
$$;

-- ==========================================
-- 3. Core tables (idempotent creation)
-- ==========================================
CREATE TABLE IF NOT EXISTS public.cash (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
    amount NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.incomes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    amount NUMERIC(12, 2) NOT NULL CHECK (amount >= 0),
    source TEXT NOT NULL,
    date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.expenses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    amount NUMERIC(12, 2) NOT NULL CHECK (amount >= 0),
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.people (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(user_id, name)
);

CREATE TABLE IF NOT EXISTS public.debts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    person_id UUID NOT NULL REFERENCES public.people(id) ON DELETE CASCADE,
    amount NUMERIC(12, 2) NOT NULL CHECK (amount >= 0),
    type debt_type NOT NULL,
    date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.savings_goals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    target_amount NUMERIC(12, 2) NOT NULL CHECK (target_amount > 0),
    monthly_amount NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    saved_amount NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    status goal_status NOT NULL DEFAULT 'active',
    last_deduction_date TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ==========================================
-- 4. Enable Row Level Security (RLS)
-- ==========================================
ALTER TABLE public.cash ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.incomes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.people ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.debts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.savings_goals ENABLE ROW LEVEL SECURITY;

-- ==========================================
-- 5. RLS Policies (USING + WITH CHECK), cast auth.uid()
-- ==========================================
-- cash: single-row-per-user assumed
DROP POLICY IF EXISTS cash_user_policy ON public.cash;
CREATE POLICY cash_user_policy ON public.cash
  FOR ALL
  TO authenticated
  USING ((SELECT auth.uid())::uuid = user_id)
  WITH CHECK ((SELECT auth.uid())::uuid = user_id);

DROP POLICY IF EXISTS incomes_user_policy ON public.incomes;
CREATE POLICY incomes_user_policy ON public.incomes
  FOR ALL
  TO authenticated
  USING ((SELECT auth.uid())::uuid = user_id)
  WITH CHECK ((SELECT auth.uid())::uuid = user_id);

DROP POLICY IF EXISTS expenses_user_policy ON public.expenses;
CREATE POLICY expenses_user_policy ON public.expenses
  FOR ALL
  TO authenticated
  USING ((SELECT auth.uid())::uuid = user_id)
  WITH CHECK ((SELECT auth.uid())::uuid = user_id);

DROP POLICY IF EXISTS people_user_policy ON public.people;
CREATE POLICY people_user_policy ON public.people
  FOR ALL
  TO authenticated
  USING ((SELECT auth.uid())::uuid = user_id)
  WITH CHECK ((SELECT auth.uid())::uuid = user_id);

DROP POLICY IF EXISTS debts_user_policy ON public.debts;
CREATE POLICY debts_user_policy ON public.debts
  FOR ALL
  TO authenticated
  USING (
    (SELECT auth.uid())::uuid = user_id
  )
  WITH CHECK (
    (SELECT auth.uid())::uuid = user_id
    AND EXISTS (
      SELECT 1 FROM public.people p
      WHERE p.id = person_id AND p.user_id = (SELECT auth.uid())::uuid
    )
  );

DROP POLICY IF EXISTS savings_goals_user_policy ON public.savings_goals;
CREATE POLICY savings_goals_user_policy ON public.savings_goals
  FOR ALL
  TO authenticated
  USING ((SELECT auth.uid())::uuid = user_id)
  WITH CHECK ((SELECT auth.uid())::uuid = user_id);

-- ==========================================
-- 6. Trigger function to update updated_at and attach to cash
-- ==========================================
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

-- Restrict execute for lower roles
REVOKE EXECUTE ON FUNCTION public.update_updated_at_column() FROM anon, authenticated;

-- Replace trigger on cash (safe: drop if exists)
DROP TRIGGER IF EXISTS update_cash_updated_at ON public.cash;

CREATE TRIGGER update_cash_updated_at
  BEFORE UPDATE ON public.cash
  FOR EACH ROW
  EXECUTE PROCEDURE public.update_updated_at_column();

-- ==========================================
-- 7. Helpful indexes for performance
-- ==========================================
CREATE INDEX IF NOT EXISTS idx_incomes_user_date ON public.incomes(user_id, date DESC);
CREATE INDEX IF NOT EXISTS idx_expenses_user_date ON public.expenses(user_id, date DESC);
CREATE INDEX IF NOT EXISTS idx_people_user_name ON public.people(user_id, name);
CREATE INDEX IF NOT EXISTS idx_debts_user_person ON public.debts(user_id, person_id);
CREATE INDEX IF NOT EXISTS idx_savings_goals_user ON public.savings_goals(user_id);

-- ==========================================
-- End of script
-- ==========================================

