                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setFormData({...formData, debt_type: 'owe_me'})} className={`h-14 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${formData.debt_type === 'owe_me' ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-500/20' : 'glass text-slate-500'}`}>Lent Money</button>
