  const [stats, setStats] = useState<DashboardStats>({
    totalCash: 0, totalIncome: 0, totalExpenses: 0, totalOwedToMe: 0, totalIOwe: 0, netBalance: 0, totalSavings: 0,
  });

  const [incomes, setIncomes] = useState<Income[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [goals, setGoals] = useState<SavingsGoal[]>([]);
  const [people, setPeople] = useState<Person[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeModal, setActiveModal] = useState<'income' | 'expense' | 'debt' | 'cash' | 'savings_goal' | null>(null);

  const fetchData = useCallback(async () => {
    try {
      const [{ data: cash }, { data: inc }, { data: exp }, { data: dbt }, { data: ppl }, { data: gls }] = await Promise.all([
        supabase.from('cash').select('*').maybeSingle(),
        supabase.from('incomes').select('*').order('date', { ascending: false }),
        supabase.from('expenses').select('*').order('date', { ascending: false }),
        supabase.from('debts').select('*, people(*)').order('date', { ascending: false }),
        supabase.from('people').select('*').order('name', { ascending: true }),
        supabase.from('savings_goals').select('*').order('created_at', { ascending: false })
      ]);

      const totalCash = cash?.amount ? Number(cash.amount) : 0;
      const totalIncome = inc?.reduce((a, b) => a + Number(b.amount), 0) || 0;
      const totalExpenses = exp?.reduce((a, b) => a + Number(b.amount), 0) || 0;
      const totalOwedToMe = dbt?.filter(d => d.type === 'owe_me').reduce((a, b) => a + Number(b.amount), 0) || 0;
      const totalIOwe = dbt?.filter(d => d.type === 'i_owe').reduce((a, b) => a + Number(b.amount), 0) || 0;
      const totalSavings = gls?.reduce((a, b) => a + Number(b.saved_amount), 0) || 0;

      setStats({
        totalCash, totalIncome, totalExpenses, totalOwedToMe, totalIOwe, totalSavings,
        netBalance: totalCash + totalOwedToMe - totalIOwe + totalSavings,
      });
      setIncomes(inc || []); setExpenses(exp || []); setDebts(dbt || []); setPeople(ppl || []); setGoals(gls || []);
    } catch (e) { 
      console.warn("Drahmi fetch error:", e); 
    } finally { 
      setLoading(false); 
    }
  }, [user.id]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const resetCash = async () => {
    if (!window.confirm('Reset liquid cash to 0.00 DA?')) return;
    try {
      const { error } = await supabase.from('cash').update({ amount: 0 }).eq('user_id', user.id);
      if (error) throw error;
      fetchData();
    } catch (err: any) {
      alert('Reset failed: ' + err.message);
    }
  };

  const deleteGoal = async (id: string) => {
    if (!window.confirm('Dissolve this savings goal?')) return;
    const { error } = await supabase.from('savings_goals').delete().eq('id', id);
    if (error) alert('Error: ' + error.message);
    else fetchData();
  };

  const deleteDebt = async (id: string) => {
    if (!window.confirm('Clear this debt record?')) return;
    const { error } = await supabase.from('debts').delete().eq('id', id);
    if (error) alert('Error: ' + error.message);
    else fetchData();
  };

  const TabItem = ({ view, label, icon: Icon }: { view: View, label: string, icon: any }) => (
    <button
      onClick={() => setActiveView(view)}
      className={`flex-1 flex flex-col items-center justify-center gap-1 transition-all duration-300 interactive-active ${
        activeView === view ? 'text-blue-500' : 'text-slate-500'
      }`}
    >
      <Icon />
      <span className="text-[8px] font-black uppercase tracking-[0.1em]">{label}</span>
    </button>
  );

  const getPersonBalance = (personId: string) => {
    const personDebts = debts.filter(d => d.person_id === personId);
    const owedToMe = personDebts.filter(d => d.type === 'owe_me').reduce((a, b) => a + Number(b.amount), 0);
    const iOwe = personDebts.filter(d => d.type === 'i_owe').reduce((a, b) => a + Number(b.amount), 0);
    return owedToMe - iOwe;
  };

  if (loading && incomes.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center bg-slate-950">
        <div className="w-8 h-8 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      <div className="scroll-container px-5 pt-8">
        <header className="flex flex-col gap-4 mb-8">
          <div className="flex items-center justify-between">
            <h1 className="text-2xl font-black tracking-tight text-white">Drahmi</h1>
            <div className="w-8 h-8 rounded-full bg-blue-600/20 flex items-center justify-center text-[10px] font-bold text-blue-400">
              {user.email?.charAt(0).toUpperCase()}
            </div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <button onClick={() => setActiveModal('income')} className="h-11 glass rounded-2xl text-[10px] font-bold uppercase tracking-widest text-emerald-400 flex items-center justify-center gap-2 interactive-active">
              <Icons.Plus /> Inflow
            </button>
            <button onClick={() => setActiveModal('expense')} className="h-11 bg-white text-slate-950 rounded-2xl text-[10px] font-bold uppercase tracking-widest flex items-center justify-center interactive-active">
              Outflow
            </button>
          </div>
        </header>

        {activeView === 'home' && (
          <div className="space-y-6 animate-fade-in">
            <div className="premium-card p-6 shadow-xl relative overflow-hidden">
              <div className="flex justify-between items-start mb-4">
                <p className="text-slate-500 text-[9px] font-black uppercase tracking-[0.2em]">Net Capital</p>
                <button onClick={() => setActiveModal('cash')} className="text-blue-500 text-[8px] font-black uppercase tracking-widest bg-blue-500/10 px-2 py-1 rounded-lg">Update</button>
              </div>
              <h3 className="text-3xl font-black tracking-tighter text-white mb-6">
                <span className="text-blue-500 text-lg mr-1">DA</span>
                {stats.netBalance.toLocaleString()}
              </h3>
              <div className="flex justify-between border-t border-white/5 pt-4">
                <div className="flex flex-col group relative" onClick={resetCash}>
                  <span className="text-[8px] text-slate-500 font-bold uppercase flex items-center gap-1 cursor-pointer">Liquid <Icons.Reset /></span>
                  <span className="text-sm font-bold">{stats.totalCash.toLocaleString()}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[8px] text-slate-500 font-bold uppercase">Vaulted</span>
                  <span className="text-sm font-bold text-emerald-400">{stats.totalSavings.toLocaleString()}</span>
                </div>
                <div className="flex flex-col text-right">
                  <span className="text-[8px] text-slate-500 font-bold uppercase">Lent</span>
                  <span className="text-sm font-bold text-blue-400">{stats.totalOwedToMe.toLocaleString()}</span>
                </div>
              </div>
            </div>

            <TransactionList title="Recent Flux" incomes={incomes.slice(0, 5)} expenses={expenses.slice(0, 5)} onRefresh={fetchData} />
          </div>
        )}

        {activeView === 'history' && (
          <div className="animate-fade-in">
            <TransactionList title="Master Ledger" incomes={incomes} expenses={expenses} onRefresh={fetchData} />
          </div>
        )}

        {activeView === 'savings' && (
          <div className="space-y-6 animate-fade-in">
            <div className="flex justify-between items-center px-1">
              <h2 className="text-xl font-black text-white">The Vault</h2>
              <button onClick={() => setActiveModal('savings_goal')} className="h-8 px-4 bg-emerald-600 rounded-full text-[9px] font-black uppercase tracking-widest text-white interactive-active">New Goal</button>
            </div>
            {goals.length === 0 ? (
              <div className="text-center py-20 opacity-20 italic text-sm">No active objectives.</div>
            ) : (
              goals.map(goal => (
                <div key={goal.id} className="premium-card p-5 space-y-4 relative">
                  <div className="flex justify-between items-start">
                    <div>
                      <h4 className="font-bold text-white text-lg">{goal.name}</h4>
                      <p className="text-[8px] text-slate-500 uppercase tracking-widest mt-1">Goal: {Number(goal.target_amount).toLocaleString()} DA</p>
                    </div>
                    <button onClick={() => deleteGoal(goal.id)} className="w-8 h-8 rounded-lg bg-rose-500/10 text-rose-500 flex items-center justify-center interactive-active">
                      <Icons.Trash />
                    </button>
                  </div>
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-black">{Number(goal.saved_amount).toLocaleString()}</span>
                    <span className="text-slate-500 text-xs font-bold">DA</span>
                  </div>
                  <div className="w-full bg-white/5 h-2 rounded-full overflow-hidden">
                    <div className="bg-emerald-500 h-full rounded-full transition-all duration-700" style={{ width: `${Math.min(100, (Number(goal.saved_amount)/Number(goal.target_amount))*100)}%` }}></div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeView === 'debts' && (
          <div className="space-y-6 animate-fade-in pb-12">
             <div className="flex justify-between items-center px-1">
                <h2 className="text-xl font-black text-white">Counterparties</h2>
                <button onClick={() => setActiveModal('debt')} className="h-8 px-4 bg-blue-600 rounded-full text-[9px] font-black uppercase tracking-widest text-white interactive-active">Add Debt</button>
             </div>

             {/* People Summary Section */}
             <div className="premium-card p-5">
                <h3 className="text-[9px] font-black uppercase tracking-widest text-slate-500 mb-4">Network Balance</h3>
                <div className="space-y-4">
                  {people.length === 0 ? (
                    <p className="text-[10px] text-slate-600 italic text-center py-4">No counterparties recorded yet.</p>
                  ) : (
                    people.map(person => {
                      const balance = getPersonBalance(person.id);
                      return (
                        <div key={person.id} className="flex items-center justify-between group">
                          <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-slate-400">
                              <Icons.UserCircle />
                            </div>
                            <span className="font-bold text-sm text-white">{person.name}</span>
                          </div>
                          <div className="text-right">
                            <p className={`text-sm font-black ${balance > 0 ? 'text-emerald-400' : balance < 0 ? 'text-rose-400' : 'text-slate-500'}`}>
                              {balance > 0 ? '+' : ''}{balance.toLocaleString()} <span className="text-[10px]">DA</span>
                            </p>
                            <p className="text-[8px] text-slate-600 uppercase font-bold">
                              {balance > 0 ? 'Owes You' : balance < 0 ? 'You Owe' : 'Settled'}
                            </p>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>
             </div>

             {/* Receivables & Payables detail */}
             <div className="grid grid-cols-1 gap-4">
                <div className="premium-card p-5">
                  <h3 className="text-xs font-black uppercase tracking-widest text-emerald-400 mb-4">Receivables (Owed to Me)</h3>
                  <div className="space-y-2">
                    {debts.filter(d => d.type === 'owe_me').length === 0 ? <p className="text-[10px] opacity-20 italic">None.</p> : debts.filter(d => d.type === 'owe_me').map(d => (
                      <div key={d.id} className="flex justify-between items-center p-3 rounded-xl bg-white/5 border border-white/5">
                        <div className="min-w-0">
                          <span className="font-bold text-sm block truncate text-white">{d.person?.name || 'Unknown'}</span>
                          <span className="text-[8px] text-slate-500 uppercase">{new Date(d.date).toLocaleDateString()}</span>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="text-emerald-400 font-bold text-sm">+{Number(d.amount).toLocaleString()}</span>
                          <button onClick={() => deleteDebt(d.id)} className="p-2 text-slate-600 hover:text-rose-500 transition-colors">
                            <Icons.Trash />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="premium-card p-5">
                  <h3 className="text-xs font-black uppercase tracking-widest text-rose-400 mb-4">Payables (I Owe)</h3>
                  <div className="space-y-2">
                    {debts.filter(d => d.type === 'i_owe').length === 0 ? <p className="text-[10px] opacity-20 italic">None.</p> : debts.filter(d => d.type === 'i_owe').map(d => (
                      <div key={d.id} className="flex justify-between items-center p-3 rounded-xl bg-white/5 border border-white/5">
                        <div className="min-w-0">
                          <span className="font-bold text-sm block truncate text-white">{d.person?.name || 'Unknown'}</span>
                          <span className="text-[8px] text-slate-500 uppercase">{new Date(d.date).toLocaleDateString()}</span>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="text-rose-400 font-bold text-sm">-{Number(d.amount).toLocaleString()}</span>
                          <button onClick={() => deleteDebt(d.id)} className="p-2 text-slate-600 hover:text-rose-500 transition-colors">
                            <Icons.Trash />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
             </div>
          </div>
        )}

        {activeView === 'settings' && (
          <div className="animate-fade-in">
            <div className="premium-card p-8 text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-3xl flex items-center justify-center text-2xl font-black mx-auto mb-4">
                {user.email?.charAt(0).toUpperCase()}
              </div>
              <h3 className="text-lg font-black">{user.email?.split('@')[0]}</h3>
              <p className="text-slate-500 text-[10px] mb-8 uppercase tracking-widest">{user.email}</p>
              <div className="space-y-3">
                 <button onClick={() => supabase.auth.signOut()} className="w-full h-12 bg-rose-500/10 text-rose-500 rounded-2xl text-[10px] font-black uppercase tracking-widest interactive-active">Logout</button>
              </div>
            </div>
          </div>
        )}
      </div>

      <nav className="fixed bottom-0 left-0 right-0 glass border-t border-white/5 z-50 flex px-2 bg-slate-950/80" style={{ height: 'calc(64px + env(safe-area-inset-bottom))', paddingBottom: 'env(safe-area-inset-bottom)' }}>
        <TabItem view="home" label="Core" icon={Icons.Home} />
        <TabItem view="history" label="Ledger" icon={Icons.History} />
        <TabItem view="savings" label="Vault" icon={Icons.Savings} />
        <TabItem view="debts" label="Credit" icon={Icons.Vault} />
        <TabItem view="settings" label="Profile" icon={Icons.Profile} />
      </nav>

      {activeModal && <Modal type={activeModal} people={people} onClose={() => setActiveModal(null)} onSuccess={() => { setActiveModal(null); fetchData(); }} />}
    </div>
  );
};

type View = 'home' | 'history' | 'debts' | 'savings' | 'settings';
export default Dashboard;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { Person, SavingsGoal } from '../types';

interface ModalProps {
  type: 'income' | 'expense' | 'debt' | 'cash' | 'savings_goal';
  people: Person[];
  onClose: () => void;
  onSuccess: () => void;
}

const Modal: React.FC<ModalProps> = ({ type, people, onClose, onSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [deductionNotice, setDeductionNotice] = useState<string | null>(null);
  const [personSearch, setPersonSearch] = useState('');
  const [formData, setFormData] = useState({
    amount: '',
    source: '',
    title: '',
    category: 'Lifestyle',
    date: new Date().toISOString().split('T')[0],
    person_name: '',
    person_id: '',
    debt_type: 'owe_me' as 'owe_me' | 'i_owe',
    goal_name: '',
    target_amount: '',
    recurring_amount: '',
    frequency: 'monthly' as 'daily' | 'monthly'
  });

  const filteredPeople = people.filter(p => 
    p.name.toLowerCase().includes(personSearch.toLowerCase())
  );

  const updateLiquidCash = async (userId: string, adjustment: number) => {
    const { data: currentCash, error: fetchError } = await supabase
      .from('cash')
      .select('*')
      .eq('user_id', userId)
      .maybeSingle();

    if (fetchError) throw fetchError;

    if (currentCash) {
      const newAmount = Math.max(0, Number(currentCash.amount) + adjustment);
      const { error: updateError } = await supabase
        .from('cash')
        .update({ 
          amount: newAmount,
          updated_at: new Date().toISOString() 
        })
        .eq('id', currentCash.id);
      if (updateError) throw updateError;
    } else {
      const { error: insertError } = await supabase
        .from('cash')
        .insert([{ user_id: userId, amount: Math.max(0, adjustment) }]);
      if (insertError) throw insertError;
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setDeductionNotice(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("User session not found.");

      if (type === 'income') {
        const amt = parseFloat(formData.amount);
        if (isNaN(amt)) throw new Error("Invalid amount");
        let cashToAddToLiquid = amt;

        // 1. Check for due savings goals to Auto-Save
        const { data: activeGoals, error: goalQueryError } = await supabase
          .from('savings_goals')
          .select('*')
          .eq('status', 'active')
          .eq('user_id', user.id);

        if (goalQueryError) {
            console.warn("Could not process auto-save goals:", goalQueryError.message);
        } else if (activeGoals && activeGoals.length > 0) {
          const today = new Date();
          const todayKey = today.toISOString().split('T')[0];
          const monthKey = `${today.getFullYear()}-${today.getMonth()}`;

          for (const goal of activeGoals as SavingsGoal[]) {
            const lastDate = goal.last_deduction_date ? new Date(goal.last_deduction_date) : null;
            let isDue = false;

            if (!lastDate) {
              isDue = true;
            } else {
              if (goal.frequency === 'daily') {
                isDue = lastDate.toISOString().split('T')[0] !== todayKey;
              } else {
                const lastMonthKey = `${lastDate.getFullYear()}-${lastDate.getMonth()}`;
                isDue = lastMonthKey !== monthKey;
              }
            }

            if (isDue && Number(goal.monthly_amount) > 0) {
              const deduction = Math.min(Number(goal.monthly_amount), cashToAddToLiquid);
              if (deduction > 0) {
                const newSaved = Number(goal.saved_amount) + deduction;

                const { error: updGoalErr } = await supabase.from('savings_goals').update({
                  saved_amount: newSaved,
                  last_deduction_date: today.toISOString(),
                  status: newSaved >= Number(goal.target_amount) ? 'completed' : 'active'
                }).eq('id', goal.id);

                if (!updGoalErr) {
                  cashToAddToLiquid -= deduction;
                  setDeductionNotice(`${deduction.toLocaleString()} DA automatically vaulted for "${goal.name}"`);
                  await new Promise(r => setTimeout(r, 1500));
                }
              }
            }
          }
        }

        await updateLiquidCash(user.id, cashToAddToLiquid);
        const { error: incomeInsertError } = await supabase.from('incomes').insert([{ 
          user_id: user.id, 
          amount: amt, 
          source: formData.source, 
          date: formData.date 
        }]);
        if (incomeInsertError) throw incomeInsertError;

      } 
      else if (type === 'expense') {
        const amt = parseFloat(formData.amount);
        await updateLiquidCash(user.id, -amt);
        await supabase.from('expenses').insert([{ user_id: user.id, title: formData.title, amount: amt, category: formData.category, date: formData.date }]);
      } 
      else if (type === 'cash') {
        const amt = parseFloat(formData.amount);
        const { data: existing } = await supabase.from('cash').select('*').eq('user_id', user.id).maybeSingle();
        if (existing) {
          await supabase.from('cash').update({ amount: amt, updated_at: new Date().toISOString() }).eq('id', existing.id);
        } else {
          await supabase.from('cash').insert([{ user_id: user.id, amount: amt }]);
        }
      } 
      else if (type === 'debt') {
        const amt = parseFloat(formData.amount);
        let pId = formData.person_id;

        // If no ID is selected but a name is typed, create a new person
        if (!pId && personSearch) {
          const { data: newPerson, error: pErr } = await supabase
            .from('people')
            .insert([{ user_id: user.id, name: personSearch }])
            .select().single();
          if (pErr) throw pErr;
          pId = newPerson?.id;
        } else if (!pId) {
          throw new Error("Please specify a counterparty name.");
        }

        const adjustment = formData.debt_type === 'owe_me' ? -amt : amt;
        await updateLiquidCash(user.id, adjustment);
        const { error: dbtErr } = await supabase.from('debts').insert([{ 
          user_id: user.id, 
          person_id: pId, 
          amount: amt, 
          type: formData.debt_type, 
          date: formData.date 
        }]);
        if (dbtErr) throw dbtErr;
      }
      else if (type === 'savings_goal') {
        const { error: goalError } = await supabase.from('savings_goals').insert([{
          user_id: user.id,
          name: formData.goal_name,
          target_amount: parseFloat(formData.target_amount),
          monthly_amount: parseFloat(formData.recurring_amount),
          frequency: formData.frequency,
          saved_amount: 0,
          status: 'active',
          start_date: new Date().toISOString()
        }]);
        if (goalError) throw goalError;
      }

      onSuccess();
    } catch (err: any) {
      console.error("Drahmi Database Error:", err);
      alert("Command Failed: " + (err.message || "Unknown error"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center bg-slate-950/90 backdrop-blur-xl p-4">
      <div className="absolute inset-0" onClick={onClose}></div>
      <div className="w-full max-w-xl glass rounded-[40px] p-8 shadow-2xl relative z-10 animate-fade-in border-white/10 overflow-hidden">

        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="text-2xl font-black tracking-tighter text-white capitalize">{type.replace('_', ' ')}</h2>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">Wealth Protocol</p>
          </div>
          <button onClick={onClose} className="w-10 h-10 glass rounded-full text-slate-500 hover:text-white flex items-center justify-center interactive-active">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        {deductionNotice && (
          <div className="mb-6 p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl animate-fade-in text-center">
            <p className="text-emerald-400 text-[10px] font-black uppercase tracking-widest">✨ Auto-Save Protocol</p>
            <p className="text-white text-xs font-bold mt-1">{deductionNotice}</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
          {type === 'savings_goal' ? (
            <div className="space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Objective Name</label>
                <input required type="text" placeholder="e.g. New Studio" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none focus:border-blue-500/50" value={formData.goal_name} onChange={e => setFormData({...formData, goal_name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Target Total (DA)</label>
                  <input required type="number" placeholder="Sum" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.target_amount} onChange={e => setFormData({...formData, target_amount: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Cadence</label>
                  <select className="w-full h-14 glass rounded-2xl px-5 text-white outline-none bg-slate-900" value={formData.frequency} onChange={e => setFormData({...formData, frequency: e.target.value as any})}>
                    <option value="daily">Daily Save</option>
                    <option value="monthly">Monthly Save</option>
                  </select>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Recurring Amount (DA)</label>
                <input required type="number" placeholder="Auto-deduct amount" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.recurring_amount} onChange={e => setFormData({...formData, recurring_amount: e.target.value})} />
              </div>
            </div>
          ) : (
            <>
              <div className="space-y-2 text-center py-4">
                <label className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">DA VOLUME</label>
                <input required type="number" step="0.01" placeholder="0.00" className="w-full h-20 bg-transparent border-none text-center text-6xl font-black text-white outline-none placeholder:text-slate-900 tracking-tighter" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} />
              </div>

              <div className="grid grid-cols-1 gap-4">
                {type === 'income' && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Capital Source</label>
                    <input required type="text" placeholder="Salary, Project, Sale..." className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.source} onChange={e => setFormData({...formData, source: e.target.value})} />
                  </div>
                )}
                {type === 'expense' && (
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Item</label>
                      <input required type="text" placeholder="Coffee, Rent..." className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Sector</label>
                      <select className="w-full h-14 glass rounded-2xl px-5 text-white outline-none bg-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        <option>Lifestyle</option><option>Vitals</option><option>Fixed Assets</option><option>Misc</option>
                      </select>
                    </div>
                  </div>
                )}
                {type === 'debt' && (
                  <div className="space-y-4">
                    <div className="space-y-2 relative">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Counterparty Name</label>
                      <input 
                        required type="text" placeholder="Search existing or type new..." 
                        className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" 
                        value={personSearch} 
                        onChange={e => {
                          setPersonSearch(e.target.value);
                          setFormData({...formData, person_id: ''}); // If typing, reset ID
                        }} 
                      />
                      {personSearch && formData.person_id === '' && filteredPeople.length > 0 && (
                        <div className="absolute top-full left-0 right-0 mt-2 glass rounded-2xl overflow-hidden z-50 shadow-2xl border border-white/10 max-h-40 overflow-y-auto">
                          {filteredPeople.map(p => (
                            <button 
                              key={p.id} type="button" 
                              onClick={() => {
                                setPersonSearch(p.name);
                                setFormData({...formData, person_id: p.id});
                              }}
                              className="w-full text-left px-5 py-4 hover:bg-white/10 text-sm font-bold border-b border-white/5 last:border-0 text-white"
                            >
                              {p.name}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setFormData({...formData, debt_type: 'owe_me'})} className={`h-14 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${formData.debt_type === 'owe_me' ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-500/20' : 'glass text-slate-500'}`}>Lent (They Owe Me)</button>
                      <button type="button" onClick={() => setFormData({...formData, debt_type: 'i_owe'})} className={`h-14 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${formData.debt_type === 'i_owe' ? 'bg-rose-600 text-white shadow-xl shadow-rose-500/20' : 'glass text-slate-500'}`}>Borrowed (I Owe Them)</button>
                    </div>
                  </div>
                )}
                {type !== 'cash' && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Event Date</label>
                    <input required type="date" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                  </div>
                )}
              </div>
            </>
          )}

          <div className="pt-4">
            <button type="submit" disabled={loading} className="w-full h-16 bg-white text-slate-950 font-black text-sm rounded-2xl shadow-2xl hover:bg-slate-200 disabled:opacity-50 uppercase tracking-[0.2em] transition-all interactive-active">
              {loading ? 'Processing Protocol...' : 'Confirm Transaction'}
            </button>
          </div>
        </form>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default Modal;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { Person, SavingsGoal } from '../types';

interface ModalProps {
  type: 'income' | 'expense' | 'debt' | 'cash' | 'savings_goal';
  people: Person[];
  onClose: () => void;
  onSuccess: () => void;
}

const Modal: React.FC<ModalProps> = ({ type, people, onClose, onSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [deductionNotice, setDeductionNotice] = useState<string | null>(null);
  const [personSearch, setPersonSearch] = useState('');
  const [formData, setFormData] = useState({
    amount: '',
    source: '',
    title: '',
    category: 'Lifestyle',
    date: new Date().toISOString().split('T')[0],
    person_name: '',
    person_id: '',
    debt_type: 'owe_me' as 'owe_me' | 'i_owe',
    goal_name: '',
    target_amount: '',
    recurring_amount: '',
    frequency: 'monthly' as 'daily' | 'monthly'
  });

  const filteredPeople = people.filter(p => 
    p.name.toLowerCase().includes(personSearch.toLowerCase())
  );

  const updateLiquidCash = async (userId: string, adjustment: number) => {
    const { data: currentCash, error: fetchError } = await supabase
      .from('cash')
      .select('*')
      .eq('user_id', userId)
      .maybeSingle();

    if (fetchError) throw fetchError;

    if (currentCash) {
      const newAmount = Math.max(0, Number(currentCash.amount) + adjustment);
      const { error: updateError } = await supabase
        .from('cash')
        .update({ 
          amount: newAmount,
          updated_at: new Date().toISOString() 
        })
        .eq('id', currentCash.id);
      if (updateError) throw updateError;
    } else {
      const { error: insertError } = await supabase
        .from('cash')
        .insert([{ user_id: userId, amount: Math.max(0, adjustment) }]);
      if (insertError) throw insertError;
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setDeductionNotice(null);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("User session not found.");

      if (type === 'income') {
        const amt = parseFloat(formData.amount);
        if (isNaN(amt)) throw new Error("Invalid amount");
        let cashToAddToLiquid = amt;
        let totalDiverted = 0;

        // Auto-Save Protocol Logic
        const { data: activeGoals, error: goalQueryError } = await supabase
          .from('savings_goals')
          .select('*')
          .eq('status', 'active')
          .eq('user_id', user.id);

        if (!goalQueryError && activeGoals && activeGoals.length > 0) {
          const today = new Date();
          const todayStr = today.toISOString().split('T')[0];

          for (const goal of activeGoals as SavingsGoal[]) {
            const lastDate = goal.last_deduction_date ? new Date(goal.last_deduction_date) : new Date(goal.start_date);
            let isDue = false;
            let multiplier = 1;

            if (goal.frequency === 'daily') {
              const diffTime = Math.abs(today.getTime() - lastDate.getTime());
              const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
              if (diffDays >= 1) {
                isDue = true;
                multiplier = diffDays;
              }
            } else {
              // Monthly check
              const isSameMonth = lastDate.getMonth() === today.getMonth() && lastDate.getFullYear() === today.getFullYear();
              if (!isSameMonth) {
                isDue = true;
              }
            }

            if (isDue && Number(goal.monthly_amount) > 0) {
              const singleDeduction = Number(goal.monthly_amount);
              const totalRequired = singleDeduction * multiplier;

              // Only deduct if we have enough from this specific income
              const actualDeduction = Math.min(totalRequired, cashToAddToLiquid);

              if (actualDeduction > 0) {
                const newSaved = Number(goal.saved_amount) + actualDeduction;
                const { error: updGoalErr } = await supabase.from('savings_goals').update({
                  saved_amount: newSaved,
                  last_deduction_date: today.toISOString(),
                  status: newSaved >= Number(goal.target_amount) ? 'completed' : 'active'
                }).eq('id', goal.id);

                if (!updGoalErr) {
                  cashToAddToLiquid -= actualDeduction;
                  totalDiverted += actualDeduction;
                }
              }
            }
          }
        }

        if (totalDiverted > 0) {
          setDeductionNotice(`${totalDiverted.toLocaleString()} DA diverted to your Vault goals.`);
          // Pause slightly so user can read the notice
          await new Promise(r => setTimeout(r, 1200));
        }

        await updateLiquidCash(user.id, cashToAddToLiquid);
        await supabase.from('incomes').insert([{ 
          user_id: user.id, 
          amount: amt, 
          source: formData.source, 
          date: formData.date 
        }]);

      } 
      else if (type === 'expense') {
        const amt = parseFloat(formData.amount);
        await updateLiquidCash(user.id, -amt);
        await supabase.from('expenses').insert([{ user_id: user.id, title: formData.title, amount: amt, category: formData.category, date: formData.date }]);
      } 
      else if (type === 'cash') {
        const amt = parseFloat(formData.amount);
        const { data: existing } = await supabase.from('cash').select('*').eq('user_id', user.id).maybeSingle();
        if (existing) {
          await supabase.from('cash').update({ amount: amt, updated_at: new Date().toISOString() }).eq('id', existing.id);
        } else {
          await supabase.from('cash').insert([{ user_id: user.id, amount: amt }]);
        }
      } 
      else if (type === 'debt') {
        const amt = parseFloat(formData.amount);
        let pId = formData.person_id;

        if (!pId && personSearch) {
          const { data: newPerson, error: pErr } = await supabase
            .from('people')
            .insert([{ user_id: user.id, name: personSearch }])
            .select().single();
          if (pErr) throw pErr;
          pId = newPerson?.id;
        } else if (!pId) {
          throw new Error("Counterparty required.");
        }

        const adjustment = formData.debt_type === 'owe_me' ? -amt : amt;
        await updateLiquidCash(user.id, adjustment);
        await supabase.from('debts').insert([{ 
          user_id: user.id, 
          person_id: pId, 
          amount: amt, 
          type: formData.debt_type, 
          date: formData.date 
        }]);
      }
      else if (type === 'savings_goal') {
        await supabase.from('savings_goals').insert([{
          user_id: user.id,
          name: formData.goal_name,
          target_amount: parseFloat(formData.target_amount),
          monthly_amount: parseFloat(formData.recurring_amount),
          frequency: formData.frequency,
          saved_amount: 0,
          status: 'active',
          start_date: new Date().toISOString(),
          last_deduction_date: null
        }]);
      }

      onSuccess();
    } catch (err: any) {
      console.error("Drahmi Error:", err);
      alert("Command Failed: " + (err.message || "Unknown error"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center bg-slate-950/90 backdrop-blur-xl p-4">
      <div className="absolute inset-0" onClick={onClose}></div>
      <div className="w-full max-w-xl glass rounded-[40px] p-8 shadow-2xl relative z-10 animate-fade-in border-white/10 overflow-hidden">

        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="text-2xl font-black tracking-tighter text-white capitalize">{type.replace('_', ' ')}</h2>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">Wealth Command</p>
          </div>
          <button onClick={onClose} className="w-10 h-10 glass rounded-full text-slate-500 hover:text-white flex items-center justify-center interactive-active">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        {deductionNotice && (
          <div className="mb-6 p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl animate-fade-in text-center">
            <p className="text-emerald-400 text-[10px] font-black uppercase tracking-widest">✨ Auto-Vault Active</p>
            <p className="text-white text-xs font-bold mt-1">{deductionNotice}</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
          {type === 'savings_goal' ? (
            <div className="space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Asset Name</label>
                <input required type="text" placeholder="e.g. Emergency Fund" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none focus:border-blue-500/50" value={formData.goal_name} onChange={e => setFormData({...formData, goal_name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Final Target (DA)</label>
                  <input required type="number" placeholder="Sum" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.target_amount} onChange={e => setFormData({...formData, target_amount: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Frequency</label>
                  <select className="w-full h-14 glass rounded-2xl px-5 text-white outline-none bg-slate-900" value={formData.frequency} onChange={e => setFormData({...formData, frequency: e.target.value as any})}>
                    <option value="daily">Daily Saving</option>
                    <option value="monthly">Monthly Saving</option>
                  </select>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Recurring Amt (DA)</label>
                <input required type="number" placeholder="Amount per cycle" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.recurring_amount} onChange={e => setFormData({...formData, recurring_amount: e.target.value})} />
              </div>
            </div>
          ) : (
            <>
              <div className="space-y-2 text-center py-4">
                <label className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">DA VOLUME</label>
                <input required type="number" step="0.01" placeholder="0.00" className="w-full h-20 bg-transparent border-none text-center text-6xl font-black text-white outline-none placeholder:text-slate-900 tracking-tighter" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} />
              </div>

              <div className="grid grid-cols-1 gap-4">
                {type === 'income' && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Capital Source</label>
                    <input required type="text" placeholder="Salary, Side-hustle..." className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.source} onChange={e => setFormData({...formData, source: e.target.value})} />
                  </div>
                )}
                {type === 'expense' && (
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Item</label>
                      <input required type="text" placeholder="Description" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Sector</label>
                      <select className="w-full h-14 glass rounded-2xl px-5 text-white outline-none bg-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        <option>Lifestyle</option><option>Vitals</option><option>Fixed Assets</option><option>Misc</option>
                      </select>
                    </div>
                  </div>
                )}
                {type === 'debt' && (
                  <div className="space-y-4">
                    <div className="space-y-2 relative">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Counterparty</label>
                      <input 
                        required type="text" placeholder="Name" 
                        className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" 
                        value={personSearch} 
                        onChange={e => {
                          setPersonSearch(e.target.value);
                          setFormData({...formData, person_id: ''});
                        }} 
                      />
                      {personSearch && formData.person_id === '' && filteredPeople.length > 0 && (
                        <div className="absolute top-full left-0 right-0 mt-2 glass rounded-2xl overflow-hidden z-50 shadow-2xl border border-white/10 max-h-40 overflow-y-auto">
                          {filteredPeople.map(p => (
                            <button 
                              key={p.id} type="button" 
                              onClick={() => {
                                setPersonSearch(p.name);
                                setFormData({...formData, person_id: p.id});
                              }}
                              className="w-full text-left px-5 py-4 hover:bg-white/10 text-sm font-bold border-b border-white/5 last:border-0 text-white"
                            >
                              {p.name}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setFormData({...formData, debt_type: 'owe_me'})} className={`h-14 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${formData.debt_type === 'owe_me' ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-500/20' : 'glass text-slate-500'}`}>Lent</button>
                      <button type="button" onClick={() => setFormData({...formData, debt_type: 'i_owe'})} className={`h-14 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${formData.debt_type === 'i_owe' ? 'bg-rose-600 text-white shadow-xl shadow-rose-500/20' : 'glass text-slate-500'}`}>Borrowed</button>
                    </div>
                  </div>
                )}
                {type !== 'cash' && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Log Date</label>
                    <input required type="date" className="w-full h-14 glass rounded-2xl px-5 text-white outline-none" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                  </div>
                )}
              </div>
            </>
          )}

          <div className="pt-4">
            <button type="submit" disabled={loading} className="w-full h-16 bg-white text-slate-950 font-black text-sm rounded-2xl shadow-2xl hover:bg-slate-200 disabled:opacity-50 uppercase tracking-[0.2em] transition-all interactive-active">
              {loading ? 'Executing...' : 'Confirm Entry'}
            </button>
          </div>
        </form>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default Modal;
